-- Resources content for Sourcework research, Phase B: themes (CLAUDE.md, "Resources stay in
-- step with the code"). Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-themes',
  p_tool_key => 'transcription',
  p_title => 'Themes',
  p_summary => 'See what several sources say in common, decide on suggested themes, and read the evidence for and against each one.',
  p_screen_keys => array['sourcework.themes', 'sourcework.theme'],
  p_sort_order => 21,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A theme is a statement that your project’s sources bear out or push against, such as “Locals treated the fort’s tunnels as a private playground”. A topic such as “Childhood” is not a theme. Themes show how broadly something is backed, and they keep the evidence against it beside the evidence for it. Everything the model proposes waits for your decision."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Open the Themes tab"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project and select "},{"type":"text","text":"Themes","marks":[{"type":"bold"}]},{"type":"text","text":". The tab appears once the project has a research question or a data point, and its badge counts the suggestions waiting for you. "},{"type":"text","text":"Waiting for you","marks":[{"type":"bold"}]},{"type":"text","text":" lists data points still to review in each source, accepted data points that are not in a theme yet, and suggestions to decide on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review themes"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Review themes","marks":[{"type":"bold"}]},{"type":"text","text":". It first files accepted data points into the themes you have already accepted, then reads the ones left over and proposes new themes and merges between accepted themes. It takes a minute or two, and you can leave the page open in another tab."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept keeps a suggestion. Reject hides it, and it is not proposed again. Put back for review is under the Rejected filter."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit opens the theme to reword it. Saving a suggestion accepts it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A suggestion marked Reads like a topic is a subject heading rather than a claim. Edit it into a sentence that says something."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A theme marked Single source is backed by one source only. That is a flag, not a verdict."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A merge suggestion says two themes are the same claim in different words. Accepting moves the data points across and records why in the memo of the theme that stays."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Accepted themes are never reworded by a later run."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How a data point gets into a theme"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Automatically: when you accept a data point, the model checks it against your accepted themes and files it where it fits, as supporting or complicating. One that fits none waits until you accept a new theme or choose Review themes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"By hand: on a theme’s page, Add data points lists accepted data points that are not in it. The ⋮ beside a piece of evidence changes it between supporting and complicating, or removes it. A removed data point is not put back by a later run."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To make a theme yourself, choose + New theme on the Themes tab."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The theme page"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a theme to read its evidence by source, with supporting and complicating data points side by side. Select the play button to open the source at that passage. Breadth shows how many of the project’s sources and speakers back the theme. The memo is yours: Review themes never reads or changes it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only accepted data points count toward a theme. Un-accepting one removes it from the numbers without deleting it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filing and reviewing send your data points’ wording to an outside service, as extraction does."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: the table becomes cards and the evidence stacks."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-research-prompts',
  p_tool_key => 'transcription',
  p_title => 'Maintaining the research prompts',
  p_summary => 'For editors: edit the wording, try a draft against the live version, publish and roll back.',
  p_screen_keys => array['sourcework.editors'],
  p_sort_order => 20,
  p_version_note => 'Added the theme prompts',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Editors maintain the wording the research steps use. You need the Editor role on Sourcework, which an administrator grants on the user’s access screen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a prompt"}]},{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Research prompts","marks":[{"type":"bold"}]},{"type":"text","text":" from the Projects page. Choose Background, Extraction guide, Theme assignment or Theme review, edit the text and it saves itself as a draft only you can see. The wording decides what counts as a data point, when a data point belongs in a theme and how a theme should read; the shape of the answer is fixed by the code, and "},{"type":"text","text":"What the model is given and returns","marks":[{"type":"bold"}]},{"type":"text","text":" shows both."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Try a draft"}]},{"type":"paragraph","content":[{"type":"text","text":"For the extraction guide, "},{"type":"text","text":"Try this draft","marks":[{"type":"bold"}]},{"type":"text","text":" runs the live version and your draft on the same source and shows what changed: what both found, and what only one did. Nothing is added to any project, and results are kept for 14 days and are visible only to you. The other prompts do not have a trial yet."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and roll back"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Publish… asks for a one-line note about what changed, then makes the draft the live version for every project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists earlier versions with the share of data points or themes people accepted. Make live again moves an earlier version back into use. Nothing is deleted."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-13-sourcework-themes',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-13',
  p_title => 'Sourcework: themes',
  p_guide_slugs => array['sourcework-themes', 'sourcework-research', 'sourcework-research-prompts'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework projects now have a Themes tab. Review themes proposes themes from the data points you have accepted, and suggests merging themes that say the same thing. Each theme shows how many sources and speakers back it and keeps the evidence against it beside the evidence for it. Accepted data points are filed into your accepted themes as you accept them. Editors can now tune the wording for filing data points and for reviewing themes."}]}]}$body$
);
